<?php
namespace App\Http\Controllers;
use App\Models\AdvanceSalary; use App\Models\EmployeeBankAccount; use App\Models\HrAttendanceException; use App\Models\HrPayrollPreflightRun; use App\Models\User; use Illuminate\Http\Request;
class HrPayrollPreflightController extends AccountBaseController { public function index(Request $request){abort_403(!in_array(user()->permission('add_payroll'),['all'],true));$period=$request->input('period',now()->format('Y-m'));$employees=User::allEmployees(null,false,'all',user()->company_id);$ids=$employees->pluck('id');$summary=['employees'=>$ids->count(),'missing_bank_account'=>$ids->diff(EmployeeBankAccount::whereIn('user_id',$ids)->pluck('user_id'))->count(),'pending_attendance_exceptions'=>HrAttendanceException::whereIn('employee_id',$ids)->where('status','pending')->count(),'pending_advances'=>AdvanceSalary::whereIn('employee_id',$ids)->where('status','pending')->count()];$this->run=HrPayrollPreflightRun::firstOrCreate(['company_id'=>user()->company_id,'period'=>$period],['summary'=>$summary]);if($this->run->status==='open')$this->run->update(['summary'=>$summary]);$this->period=$period;return view('hr-payroll-preflight.index',$this->data);} public function approve(HrPayrollPreflightRun $run){abort_403(!in_array(user()->permission('add_payroll'),['all'],true)||$run->company_id!==user()->company_id);$run->update(['status'=>'approved','approved_by'=>user()->id,'approved_at'=>now()]);return redirect()->route('hr-payroll-preflight.index',['period'=>$run->period])->with('success','Payroll preflight approved and locked.');}}
